export type PlainObject = Record<string, unknown>;

function isPlainObject(value: unknown): value is PlainObject {
  if (value === null || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isSkippedKey(key: string): boolean {
  return key === "__proto__" || key === "constructor" || key === "prototype";
}

function deepClone(value: unknown): unknown {
  if (value === null || value === undefined) return value;

  if (isPlainObject(value)) {
    const out: PlainObject = {};
    const keys = Object.keys(value);
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      if (isSkippedKey(key)) continue;
      out[key] = deepClone(value[key]);
    }
    return out;
  }

  if (Array.isArray(value)) {
    const out: unknown[] = new Array(value.length);
    for (let i = 0; i < value.length; i++) {
      out[i] = deepClone(value[i]);
    }
    return out;
  }

  // Date, Map, Set, class instances, functions, primitives — keep by reference.
  return value;
}

export function deepMerge(...objects: PlainObject[]): PlainObject {
  const result: PlainObject = {};

  for (let s = 0; s < objects.length; s++) {
    const source = objects[s];
    if (source === null || source === undefined) continue;

    const keys = Object.keys(source);

    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      if (isSkippedKey(key)) continue;

      const incoming = source[key];
      if (incoming === undefined) continue;

      const existing = result[key];

      if (isPlainObject(existing) && isPlainObject(incoming)) {
        result[key] = deepMerge(existing, incoming);
      } else {
        result[key] = deepClone(incoming);
      }
    }
  }

  return result;
}
```

**Key design decisions:**

1. **`isPlainObject`** — checks that the value is a non-null object whose prototype is exactly `Object.prototype` or `null`. This excludes arrays, `Date`, `Map`, `Set`, class instances, and functions in one check.

2. **`deepClone`** — recursively clones plain objects (as `{}`) and arrays (as `[]`), descending into nested plain objects inside arrays and vice-versa. Every other object type is returned by reference. `undefined`/`null` short-circuit. The dangerous keys (`__proto__`, `constructor`, `prototype`) are filtered at every level, so no argument's prototype can be altered.

3. **`deepMerge`** — builds a fresh accumulator object. For each source, it iterates own-enumerable string keys (via `Object.keys`, which already excludes symbol keys). An incoming `undefined` is a no-op; `null` falls through to `deepClone` and overwrites; when both the current accumulator value and the incoming value are plain objects the merge recurses; everything else (including arrays) is deep-cloned and assigned. Because the accumulator is always a brand-new object and `deepMerge`/`deepClone` never write into their arguments, no input is mutated and no plain object or array in the result is shared with any argument.

4. **No imports, no runtime dependencies** — works identically in Deno, Node, and browsers.

